<?php declare(strict_types=1); require __DIR__ . '/lib/landlord.php'; handleLandlordPost('maintenance.php'); extract(landlordData()); renderLandlordStart('maintenance', 'Maintenance', 'Repairs and issues', 'Track reported problems from first message through to completion.', '<div class="top-actions"><button class="button primary" data-open="maintenance-dialog">Report issue</button></div>'); ?>
<section class="metrics"><article class="metric"><span>Open issues</span><strong class="warning"><?= $openMaintenance ?></strong><small>Reported or scheduled</small></article><article class="metric"><span>Urgent</span><strong><?= count(array_filter($maintenance, fn(array $item): bool => $item['priority'] === 'urgent' && $item['status'] !== 'completed')) ?></strong><small>Need prompt attention</small></article><article class="metric"><span>Completed</span><strong class="positive"><?= count(array_filter($maintenance, fn(array $item): bool => $item['status'] === 'completed')) ?></strong><small>Closed requests</small></article></section>
<section class="panel table-wrap section"><table><thead><tr><th>Issue</th><th>Property</th><th>Tenant</th><th>Priority</th><th>Status</th></tr></thead><tbody><?php foreach($maintenance as $item): ?><tr><td><strong><?= e($item['title']) ?></strong><br><small><?= e($item['description']) ?></small></td><td><?= e($item['address']) ?></td><td><?= e($item['tenant_name'] ?: 'Landlord reported') ?></td><td><span class="badge <?= $item['priority'] === 'urgent' ? 'expired' : 'due' ?>"><?= e(ucfirst($item['priority'])) ?></span></td><td><form method="post"><input type="hidden" name="csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="action" value="maintenance_status"><input type="hidden" name="maintenance_id" value="<?= (int)$item['id'] ?>"><select name="status" class="status-select <?= $item['status'] === 'completed' ? 'received' : 'pending' ?>" onchange="this.form.submit()"><?php foreach(['reported','scheduled','completed'] as $status): ?><option value="<?= $status ?>" <?= $item['status']===$status?'selected':'' ?>><?= e(ucfirst($status)) ?></option><?php endforeach; ?></select></form></td></tr><?php endforeach; ?></tbody></table></section>
<dialog id="maintenance-dialog"><form method="post"><button type="button" class="dialog-close" data-close>&times;</button><p class="eyebrow">Maintenance</p><h2>Report an issue</h2><input type="hidden" name="csrf" value="<?= e(csrfToken()) ?>"><input type="hidden" name="action" value="add_maintenance"><label>Property<select name="property_id"><?php foreach($properties as $property): ?><option value="<?= (int)$property['id'] ?>"><?= e($property['address']) ?></option><?php endforeach; ?></select></label><label>Tenant<select name="tenant_id"><option value="">Landlord reported</option><?php foreach($tenants as $tenant): ?><option value="<?= (int)$tenant['id'] ?>"><?= e($tenant['name']) ?></option><?php endforeach; ?></select></label><label>Issue title<input name="title" required></label><label>Description<textarea name="description" rows="4" required></textarea></label><label>Priority<select name="priority"><option>Normal</option><option>Low</option><option>Urgent</option></select></label><button class="button primary">Add issue</button></form></dialog>
<?php renderLandlordEnd($properties); ?>
